#include <vector>
#include <cstddef>
#include <stdexcept>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;
    if (A.size() != N * N) throw std::invalid_argument("luFactorize: A.size() must be N*N");

    // Doolittle LU without pivoting:
    // After factorization:
    //  - U is stored in the upper triangle of A (including diagonal)
    //  - L is stored in the strict lower triangle of A (unit diagonal implied)
    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];
        if (pivot == 0.0) {
            throw std::runtime_error("luFactorize: zero pivot encountered (no pivoting implemented)");
        }

        // Compute multipliers L(i,k) = A(i,k) / pivot for i=k+1..N-1
        // Each thread writes distinct A(i,k).
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Update trailing submatrix:
        // A(i,j) -= L(i,k) * U(k,j) for i,j=k+1..N-1
        // Parallelize over rows i; each thread updates a disjoint row slice.
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            const double lik = A[static_cast<size_t>(i) * N + k];
            double* row_i = &A[static_cast<size_t>(i) * N];
            const double* row_k = &A[k * N];

            for (size_t j = k + 1; j < N; ++j) {
                row_i[j] -= lik * row_k[j];
            }
        }
        // Implicit barrier at end of omp for ensures correctness for next k.
    }
}
